extern uint32_t _sidata, _sdata, _edata, _sbss, _ebss;

void Reset_Handler(void) {
    /* copy .data: Flash (LMA) -> RAM (VMA) */
    uint32_t *src = &_sidata;
    uint32_t *dst = &_sdata;
    while (dst < &_edata)
        *dst++ = *src++;

    /* zero .bss */
    for (dst = &_sbss; dst < &_ebss; dst++)
        *dst = 0;

    SystemInit();   /* clocks, optional */
    main();
    while (1) {}
}

typedef struct block {
  size_t        size;   /* bytes in this block, header included */
  struct block *next;   /* next free block (only used while free) */
} block_t;

typedef struct tcb {
  uint32_t   *sp;          /* saved stack pointer: MUST be the first member */
  struct tcb *next;        /* next task in the round-robin list */
  uint32_t   *stack_base;  /* lowest address of the task stack */
  uint32_t    stack_words;
  uint8_t     state;       /* READY, RUNNING, BLOCKED */
} tcb_t;

tcb_t *task_create(void (*entry)(void *), void *arg, size_t stack_words)
{
  tcb_t    *t     = heap_alloc(sizeof *t);
  uint32_t *stack = heap_alloc(stack_words * 4u);   /* from the allocator */
  if (!t || !stack) { return NULL; }

  t->stack_base  = stack;
  t->stack_words = stack_words;

  uint32_t *top = stack + stack_words;               /* stack grows DOWN */
  top = (uint32_t *)((uintptr_t)top & ~(uintptr_t)7);/* 8-byte aligned */
  t->sp = build_initial_frame(top, entry, arg);
  return t;
}

void SysTick_Handler(void)
{
  tick_count++;
  if (--current_tcb_slice == 0) {
    current_tcb_slice = TIME_SLICE_TICKS;
    SCB->ICSR |= SCB_ICSR_PENDSVSET_Msk;   /* ask for a context switch */
  }
}

tcb_t *sched_pick_next(void)                /* called from PendSV */
{
  tcb_t *t = current_tcb;
  do { t = t->next; } while (t->state != READY && t != current_tcb);
  return t;                                  /* skips BLOCKED tasks */
}

/* producer / consumer with two counting semaphores */
sem_t slots_free = SEM_INIT(N);   /* empty slots in the buffer */
sem_t items_ready = SEM_INIT(0);  /* filled slots */

void producer(void) { sem_take(&slots_free); put(buf, x); sem_give(&items_ready); }
void consumer(void) { sem_take(&items_ready); x = get(buf); sem_give(&slots_free); }

void lock(volatile uint32_t *m)
{
  do {
    while (__LDREXW(m) != 0) { yield(); }   /* wait while locked */
  } while (__STREXW(1, m) != 0);            /* retry if someone got in first */
  __DMB();                                  /* memory barrier */
}
void unlock(volatile uint32_t *m) { __DMB(); *m = 0; }

/* portable pseudo-API: UART_SR_TXE / UART_SR_RXNE / UART_DR stand for the status and data registers */
void uart_putc(char c)
{
  while (!(UART_SR & UART_SR_TXE)) { }   /* wait until the transmit register is empty */
  UART_DR = (uint8_t)c;
}

#define RX_SIZE 64u                       /* power of two */
static volatile uint8_t  rx_buf[RX_SIZE];
static volatile uint32_t rx_head, rx_tail;

void UART_IRQHandler(void)
{
  if (UART_SR & UART_SR_RXNE) {
    uint8_t b = (uint8_t)UART_DR;         /* reading clears the flag */
    uint32_t next = (rx_head + 1u) & (RX_SIZE - 1u);
    if (next != rx_tail) {                /* drop the byte if the buffer is full */
      rx_buf[rx_head] = b;
      rx_head = next;
    }
  }
}

int uart_getc(void)                       /* returns -1 if nothing is waiting */
{
  if (rx_tail == rx_head) { return -1; }
  uint8_t b = rx_buf[rx_tail];
  rx_tail = (rx_tail + 1u) & (RX_SIZE - 1u);
  return b;
}

uint8_t spi_xfer(uint8_t out)             /* send one byte, return the byte received */
{
  while (!(SPI_SR & SPI_SR_TXE)) { }
  SPI_DR = out;
  while (!(SPI_SR & SPI_SR_RXNE)) { }
  return (uint8_t)SPI_DR;
}

uint8_t sensor_read_reg(uint8_t reg)        /* many sensors: bit 7 set = read */
{
  cs_low();
  spi_xfer(reg | 0x80u);                    /* command byte (answer is ignored) */
  uint8_t value = spi_xfer(0x00u);          /* dummy byte produces the clocks */
  cs_high();
  return value;
}

#define DEV 0x48u                              /* 7-bit address */

int i2c_write_reg(uint8_t reg, uint8_t val)
{
  i2c_start();
  if (!i2c_send_byte((DEV << 1) | 0u)) { i2c_stop(); return -1; }   /* address + W, check ACK */
  if (!i2c_send_byte(reg))            { i2c_stop(); return -1; }
  if (!i2c_send_byte(val))            { i2c_stop(); return -1; }
  i2c_stop();
  return 0;
}

int i2c_read_reg(uint8_t reg, uint8_t *val)
{
  i2c_start();
  if (!i2c_send_byte((DEV << 1) | 0u)) { i2c_stop(); return -1; }
  if (!i2c_send_byte(reg))            { i2c_stop(); return -1; }
  i2c_start();                                    /* repeated START */
  if (!i2c_send_byte((DEV << 1) | 1u)) { i2c_stop(); return -1; }   /* address + R */
  *val = i2c_recv_byte(/*nack=*/1);               /* last byte: answer NACK */
  i2c_stop();
  return 0;
}

uint8_t spi_bb_xfer(uint8_t out)
{
  uint8_t in = 0;
  for (int i = 7; i >= 0; i--) {
    gpio_write(MOSI, (out >> i) & 1u);   /* put the bit on MOSI while SCLK is low */
    delay_us(1);
    gpio_write(SCLK, 1);                 /* rising edge: slave samples MOSI */
    in = (uint8_t)((in << 1) | gpio_read(MISO));   /* we sample MISO now */
    delay_us(1);
    gpio_write(SCLK, 0);                 /* falling edge */
  }
  return in;
}

static void sda(int v) { v ? gpio_input(SDA) : (gpio_write(SDA, 0), gpio_output(SDA)); }
static void scl(int v) { v ? gpio_input(SCL) : (gpio_write(SCL, 0), gpio_output(SCL)); }

void i2c_bb_start(void) { sda(1); scl(1); delay_us(5); sda(0); delay_us(5); scl(0); }
void i2c_bb_stop(void)  { sda(0); scl(1); delay_us(5); sda(1); delay_us(5); }

int i2c_bb_send_byte(uint8_t b)
{
  for (int i = 7; i >= 0; i--) {
    sda((b >> i) & 1u);  delay_us(2);
    scl(1);              delay_us(5);     /* receiver reads SDA while SCL is high */
    scl(0);
  }
  sda(1); delay_us(2);                    /* release SDA so the slave can ACK */
  scl(1); delay_us(5);
  int ack = (gpio_read(SDA) == 0);        /* ACK = slave pulled SDA low */
  scl(0);
  return ack;
}
